+<?php
+declare(strict_types=1);
+
+namespace Drupal\hwdesk\Service;
+
+use Drupal\Core\Entity\EntityTypeManagerInterface;
+use Drupal\hwdesk\Entity\Asset;
+use InvalidArgumentException;
+
+final class IntakeService {
+  public function __construct(
+    private readonly EntityTypeManagerInterface $entityTypeManager,
+    private readonly TagGenerator $tagGenerator,
+  ) {}
+
+  /**
+   * Create a batch of assets.
+   */
+  public function createBatch(array $values, int $count): array {
+    if ($count < 1 || $count > 500) {
+      throw new InvalidArgumentException('Count must be between 1 and 500.');
+    }
+    $type = $values['type'] ?? null;
+    $model = $values['model'] ?? null;
+    if (!is_string($type) || trim($type) === '' || !is_string($model) || trim($model) === '') {
+      throw new InvalidArgumentException('Type and model are required.');
+    }
+    $assets = [];
+    for ($i = 0; $i < $count; $i++) {
+      $asset_data = [
+        'type' => $type,
+        'model' => $model,
+        'tag' => $this->tagGenerator->next($type),
+        'status' => 'in_stock',
+        'holder' => NULL,
+      ];
+      if (isset($values['manufacturer'])) {
+        $asset_data['manufacturer'] = $values['manufacturer'];
+      }
+      $asset_data['condition'] = $values['condition'] ?? 'new';
+      if (array_key_exists('location', $values)) {
+        $asset_data['location'] = $values['location'];
+      }
+      if (!empty($values['tags'])) {
+        $asset_data['tags'] = $values['tags'];
+      }
+      if (array_key_exists('invoice', $values)) {
+        $asset_data['invoice'] = $values['invoice'];
+      }
+      if (array_key_exists('price', $values) && $values['price'] !== NULL) {
+        // Keep as string with two decimals.
+        // Ensure price is stored as a string with exactly two decimal places.
